#include <bits/stdc++.h>
using namespace std;
const int MAXN = 1e5 + 5;
const int MAXM = 2e5 + 5; // 值域离散化后最大大小
int n = 8, m; // 初始数组长度，离散化后值域大小
int a[MAXN] = {3,1,4,1,5,9,2,6}; // 初始数组
int tree[MAXM]; // 树状数组，维护值域前缀和
vector<int> vals; // 离散化用的值域集合
// 跳表节点定义
struct SkipNode {
    int val; // 存储数组元素值
    int level;
    SkipNode** next;
    SkipNode(int v, int l) : val(v), level(l) {
        next = new SkipNode*[l+1];
        for(int i=0;i<=l;i++) next[i] = nullptr;
    }
};
SkipNode* head = new SkipNode(INT_MIN, 20); // 跳表头节点，最大层数20
// 工具函数：获取随机层数
int randomLevel() {
    int lv = 0;
    while(rand()%2 == 0 && lv < 20) lv++;
    return lv;
}
// 跳表插入操作
void skipInsert(int val) {
    SkipNode* update[21];
    SkipNode* cur = head;
    for(int i=20; i>=0; i--) {
        while(cur->next[i] != nullptr && cur->next[i]->val < val) {
            cur = cur->next[i];
        }
        update[i] = cur;
    }
    int lv = randomLevel();
    SkipNode* newNode = new SkipNode(val, lv);
    for(int i=0; i<=lv; i++) {
        newNode->next[i] = update[i]->next[i];
        update[i]->next[i] = newNode;
    }
}
// 跳表初始化，插入初始数组所有元素
void skipInit() {
    for(int i=1; i<=n; i++) {
        skipInsert(a[i]);
        vals.push_back(a[i]);
    }
}
// 离散化：获取值对应的离散化下标（1-indexed）
int getIdx(int val) {
    return lower_bound(vals.begin(), vals.end(), val) - vals.begin() + 1;
}
// 树状数组单点加
void add(int idx, int v) {
    while(idx <= m) {
        tree[idx] += v;
        idx += idx & -idx;
    }
}
// 树状数组查询前缀和
int query(int idx) {
    int res = 0;
    while(idx > 0) {
        res += tree[idx];
        idx -= idx & -idx;
    }
    return res;
}
// 查询全局第k小的数
int queryKth(int k) {
    int idx = 0;
    for(int i=20; i>=0; i--) {
        int nextIdx = idx + (1<<i);
        if(nextIdx <= m && tree[nextIdx] < k) {
            k -= tree[nextIdx];
            idx = nextIdx;
        }
    }
    return vals[idx];
}
// 处理操作
void solve() {
    skipInit();
    // 初始化树状数组：统计初始每个值的出现次数
    for(int i=1; i<=n; i++) {
        add(getIdx(a[i]), 1);
    }
    m = vals.size();
    // 去重离散化值域
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    m = vals.size();
    int q;
    cin >> q;
    while(q--) {
        int op;
        cin >> op;
        if(op == 1) {
            int pos, delta;
            cin >> pos >> delta;
            // 修改树状数组：先减旧值，再加新值
            add(getIdx(a[pos]), -1);
            a[pos] += delta;
            add(getIdx(a[pos]), 1);
            // 跳表插入新值
            skipInsert(a[pos]);
        } else if(op == 2) {
            int l, r, k;
            cin >> l >> r >> k;
            // 查询全局第k小
            cout << queryKth(k) << endl;
        }
    }
}
int main() {
    srand(time(0));
    solve();
    return 0;
}
```
